import { readFileSync, writeFileSync } from "node:fs";
const p = "capture/extracted/tokens.json";
const t = JSON.parse(readFileSync(p, "utf8"));
t.colors = ["#FAFAFA", "#09090B", "#FF6B35", "#CCFF00", "#0F766E"];
t.fonts = [
  { family: "Archivo Black", weights: [400], variable: false },
  { family: "JetBrains Mono", weights: [400, 700], variable: false },
];
t.colorStats = [
  { hex: "#FAFAFA", count: 12, bgCount: 6, interactiveBg: 0, areaBg: 6, textCount: 2, maxArea: 14000000 },
  { hex: "#09090B", count: 70, bgCount: 3, interactiveBg: 0, areaBg: 2, textCount: 64, maxArea: 1200000 },
  { hex: "#FF6B35", count: 18, bgCount: 2, interactiveBg: 4, areaBg: 1, textCount: 8, maxArea: 80000 },
  { hex: "#CCFF00", count: 4, bgCount: 1, interactiveBg: 1, areaBg: 0, textCount: 2, maxArea: 4000 },
  { hex: "#0F766E", count: 3, bgCount: 0, interactiveBg: 0, areaBg: 0, textCount: 3, maxArea: 0 },
];
writeFileSync(p, JSON.stringify(t, null, 2) + "\n");
console.log("tokens patched");
EOF
